/// Byte-exact port of line 5, `underscore(word)`.
/// Operates purely on bytes; returns bytes because the transform can be applied
/// to non-UTF-8 input (the C++ side is `std::string`).
pub fn underscore_bytes(input: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::with_capacity(input.len() * 2);
    for (i, &c) in input.iter().enumerate() {
        if c.is_ascii_uppercase() {
            // Positional test only: index > 0. No look-back at out.last().
            if i > 0 {
                out.push(b'_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// Convenience wrapper matching the `String -> String` C++ signature.
/// Safe because the transform only ever maps ASCII bytes to ASCII bytes and
/// copies all other bytes verbatim, so UTF-8 validity is preserved.
pub fn underscore(s: &str) -> String {
    String::from_utf8(underscore_bytes(s.as_bytes())).expect("utf8 preserved")
}

/// Byte-exact port of line 10, `dasherize(word)`.
pub fn dasherize_bytes(input: &[u8]) -> Vec<u8> {
    input
        .iter()
        .map(|&c| if c == b'_' { b'-' } else { c })
        .collect()
}

/// `String -> String` wrapper. Safe: 0x5F is an ASCII byte that can never occur
/// inside a multi-byte UTF-8 sequence, and 0x2D is also ASCII, so UTF-8 validity
/// and byte length are both preserved. Equivalent one-liner: `s.replace('_', "-")`.
pub fn dasherize(s: &str) -> String {
    s.bytes()
        .map(|c| if c == b'_' { '-' } else { c as char })
        .collect::<String>() // NOTE: only correct for ASCII; prefer the byte version:
}

/// Preferred UTF-8-safe wrapper.
pub fn dasherize_str(s: &str) -> String {
    String::from_utf8(dasherize_bytes(s.as_bytes())).expect("utf8 preserved")
}

/// Line 11: parameterize(word)
/// Byte-oriented; retained bytes are always ASCII so UTF-8 validity is guaranteed.
pub fn parameterize(word: &str) -> String {
    parameterize_bytes(word.as_bytes())
}

/// Line 12: parameterize("A " + word + " Test")
pub fn parameterize_line12(word: &str) -> String {
    parameterize(&format!("A {} Test", word))
}

fn parameterize_bytes(input: &[u8]) -> String {
    // STEP 1: per-byte map
    let mut out: Vec<u8> = Vec::with_capacity(input.len());
    for &b in input {
        match b {
            b'0'..=b'9' | b'a'..=b'z' => out.push(b),
            b'A'..=b'Z' => out.push(b + 32),   // ASCII-only tolower
            b' ' => out.push(b'-'),            // ONLY 0x20, not \t \n \v \f \r
            _ => {}                            // drop everything else, incl. 0x80..=0xFF
        }
    }

    // STEP 2: trim all leading and trailing '-', do NOT squeeze internal runs
    let start = match out.iter().position(|&c| c != b'-') {
        Some(i) => i,
        None => return String::new(), // empty, or entirely '-'
    };
    let end = out.iter().rposition(|&c| c != b'-').unwrap(); // start exists => end exists

    out.truncate(end + 1);
    out.drain(..start);
    String::from_utf8(out).expect("only ASCII bytes are retained")
}

fn ascii_toupper(b: u8) -> u8 {
    if b.is_ascii_lowercase() { b - 32 } else { b }
}

/// line 3: camelize(word)  — default 2nd parameter
pub fn camelize_lower(input: &str) -> String {
    let mut out: Vec<u8> = Vec::with_capacity(input.len());
    let mut cap = false;
    for &c in input.as_bytes() {
        if c == b'_' {
            cap = true;
        } else if cap {
            out.push(ascii_toupper(c));
            cap = false;
        } else {
            out.push(c);
        }
    }
    // Bytes >= 0x80 are passed through untouched, so any UTF-8 that survived
    // in the input is still valid UTF-8 here.
    unsafe { String::from_utf8_unchecked(out) }
}

/// line 4: camelize(word, false)
pub fn camelize_upper(input: &str) -> String {
    let mut out: Vec<u8> = camelize_lower(input).into_bytes();
    if let Some(first) = out.first_mut() {
        *first = ascii_toupper(*first);   // first BYTE only; no-op if not b'a'..=b'z'
    }
    unsafe { String::from_utf8_unchecked(out) }
}

fn ascii_toupper(b: u8) -> u8 { if b.is_ascii_lowercase() { b - 32 } else { b } }

pub fn humanize(input: &str) -> String {
    let mut out: Vec<u8> = input.as_bytes().to_vec();
    for b in out.iter_mut() {
        if *b == b'_' { *b = b' '; }
    }
    if !out.is_empty() {
        out[0] = ascii_toupper(out[0]);
    }
    // bytes may be non-UTF8-boundary-safe only if input was; input is valid UTF-8
    // and no byte >= 0x80 is ever modified, so from_utf8 always succeeds.
    String::from_utf8(out).unwrap()
}

fn ascii_toupper(b: u8) -> u8 { if b.is_ascii_lowercase() { b - 32 } else { b } }
fn ascii_tolower(b: u8) -> u8 { if b.is_ascii_uppercase() { b + 32 } else { b } }

pub fn titleize(input: &str) -> String {
    let mut out: Vec<u8> = Vec::with_capacity(input.len());
    let mut cap_next = true;
    for &c in input.as_bytes() {
        if c == b' ' {
            out.push(b' ');
            cap_next = true;
        } else if cap_next {
            out.push(ascii_toupper(c));
            cap_next = false;
        } else {
            out.push(ascii_tolower(c));
        }
    }
    // no byte >= 0x80 is ever modified, so UTF-8 validity is preserved.
    String::from_utf8(out).unwrap()
}

pub fn truncate(s: &[u8], len: usize) -> Vec<u8> {
    const OMISSION: &[u8] = b"...";
    if s.len() <= len {
        return s.to_vec();
    }
    // For the call under test len == 5, so keep == 2.
    let keep = len - OMISSION.len();
    let mut out = Vec::with_capacity(len);
    out.extend_from_slice(&s[..keep]);
    out.extend_from_slice(OMISSION);
    out
}

// String-typed convenience wrapper: note it must NOT use char boundaries.
pub fn truncate_str(s: &str, len: usize) -> String {
    // Safety note: the C++ result can be invalid UTF-8, so a faithful port
    // must return Vec<u8> (or use String::from_utf8_lossy) rather than &str slicing.
    String::from_utf8_lossy(&truncate(s.as_bytes(), len)).into_owned()
}

#[derive(Debug)]
pub struct OutOfRange {
    pub pos: usize,
    pub size: usize,
}
impl std::fmt::Display for OutOfRange {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(
            f,
            "basic_string::substr: __pos (which is {}) > this->size() (which is {})",
            self.pos, self.size
        )
    }
}

/// Faithful port of the C++ demodulize. Byte-based; can fail like substr does.
pub fn demodulize(s: &[u8]) -> Result<Vec<u8>, OutOfRange> {
    match s.iter().rposition(|&b| b == b':') {
        // Unreachable for line 18 ("Test::" always contains ':'), retained for fidelity.
        None => Ok(s.to_vec()),
        Some(pos) => {
            let start = pos + 2; // BUG faithfully reproduced: +2 from the last ':' itself
            if start > s.len() {
                Err(OutOfRange { pos: start, size: s.len() })
            } else {
                Ok(s[start..].to_vec())
            }
        }
    }
}

/// Exactly what line 18 does.
pub fn line18(word: &[u8]) -> Result<Vec<u8>, OutOfRange> {
    let mut s = b"Test::".to_vec();
    s.extend_from_slice(word);
    demodulize(&s)
}

/// Equivalent closed form expressed directly on `word` (same results, verified).
pub fn line18_closed_form(word: &[u8]) -> Result<Vec<u8>, OutOfRange> {
    let m = word.len();
    let size = 6 + m;
    let start_in_word: usize = match word.iter().rposition(|&b| b == b':') {
        Some(j) => j + 2, // pos = 6+j, start = 8+j, minus the 6-byte prefix
        None => 1,        // pos = 5,   start = 7,   minus the 6-byte prefix
    };
    if start_in_word > m {
        return Err(OutOfRange { pos: start_in_word + 6, size });
    }
    Ok(word[start_in_word..].to_vec())
}

