/// Byte-exact reimplementation of line 1 of test20_executable.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    // Whole-string, case-sensitive, byte-for-byte comparison.
    for u in UNCOUNTABLE.iter() {
        if word == u.as_bytes() {
            return word.to_vec();
        }
    }
    let mut out = Vec::with_capacity(word.len() + 1);
    out.extend_from_slice(word);
    out.push(b's');
    out
}

// String convenience wrapper (input may be non-UTF8 in general; prefer &[u8]).
