use std::io::Write;

fn main() {
    let argv: Vec<std::ffi::OsString> = std::env::args_os().collect();
    // argc < 2 -> print absolutely nothing, exit 0.
    if argv.len() < 2 {
        std::process::exit(0);
    }
    // argv[2..] are ignored entirely.
    // Raw bytes, not UTF-8 validated:
    use std::os::unix::ffi::OsStrExt;
    let word: Vec<u8> = argv[1].as_os_str().as_bytes().to_vec();

    // Compute ALL 20 results BEFORE emitting anything.
    let mut r: Vec<Vec<u8>> = Vec::with_capacity(20);
    r.push(pluralize(&word));
    r.push(singularize(&word));
    r.push(camelize(&word, true));
    r.push(camelize(&word, false));
    r.push(underscore(&word));
    r.push(classify(&word));
    r.push(tableize(&word));
    r.push(humanize(&word));
    r.push(titleize(&word));
    r.push(dasherize(&word));
    r.push(parameterize(&word));
    let mut wrapped = b"A ".to_vec();
    wrapped.extend_from_slice(&word);
    wrapped.extend_from_slice(b" Test");
    r.push(parameterize(&wrapped));
    r.push(upcase(&word));
    r.push(downcase(&word));
    r.push(capitalize(&word));
    r.push(decapitalize(&word));
    r.push(truncate(&word, 5));
    let mut qualified = b"Test::".to_vec();
    qualified.extend_from_slice(&word);
    r.push(demodulize_or_abort(&qualified)); // may abort(), see other entry
    r.push(if is_plural(&word)   { b"1".to_vec() } else { b"0".to_vec() });
    r.push(if is_singular(&word) { b"1".to_vec() } else { b"0".to_vec() });

    // Emit: 20 records, each followed by a single 0x0A, flushed per record.
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for line in &r {
        let _ = out.write_all(line);   // errors are IGNORED (see /dev/full probe)
        let _ = out.write_all(b"\n");
        let _ = out.flush();
    }
    std::process::exit(0);
}

