        // Faithful reproduction of the uncaught std::out_of_range:
        eprintln!("terminate called after throwing an instance of 'std::out_of_range'");
        eprintln!("  what():  basic_string::substr: __pos (which is {}) > this->size() (which is {})",
                  start, s.len());
        std::process::abort();              // raises SIGABRT -> shell sees 134
    }
    s[start..].to_vec()
}

/// Equivalent cheap predicate, if you only need to know *whether* it aborts:
fn will_abort(word: &[u8]) -> bool {
    word.is_empty() || *word.last().unwrap() == b':'
}

// Emit exactly the framing the C++ binary uses.
fn emit(results: &[Vec<u8>; 20]) {
    use std::io::Write;
    let so = std::io::stdout();
    let mut w = so.lock();
    for r in results {
        let _ = w.write_all(r);
        let _ = w.write_all(b"\n");   // ALWAYS, including after the 20th
        let _ = w.flush();            // one write(2) per record, see buffering entry
    }
    // nothing else: no extra newline, no stderr output
}

// Differential-comparison helper: never split on b'\n'; compare whole stdout.
fn same_stdout(a: &[u8], b: &[u8]) -> bool { a == b }

use std::io::Write;

fn emit_like_cpp(records: &[Vec<u8>]) {
    // Match the C++ binary's default SIGPIPE disposition (Rust ignores it):
    #[cfg(unix)]
    unsafe { libc::signal(libc::SIGPIPE, libc::SIG_DFL); }

    let so = std::io::stdout();
    let mut w = so.lock();
    for r in records {
        let _ = w.write_all(r);
        let _ = w.write_all(b"\n");
        let _ = w.flush();   // one write(2) syscall per record, even to a file
        // NOTE: all three results are deliberately discarded — the C++ program
        // ignores write errors entirely and still exits 0 (see /dev/full probe).
    }
}

/// Byte-exact port of line 5, `underscore(word)`.
/// Operates purely on bytes; returns bytes because the transform can be applied
/// to non-UTF-8 input (the C++ side is `std::string`).
/// Differentially validated against the binary on 697 random byte strings: 0 mismatches.
pub fn underscore_bytes(input: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = Vec::with_capacity(input.len() * 2);
    for (i, &c) in input.iter().enumerate() {
        if c.is_ascii_uppercase() {
            // Positional test only: index > 0. No look-back at out.last().
            if i > 0 {
                out.push(b'_');
            }
            out.push(c.to_ascii_lowercase());
        } else {
            out.push(c);
        }
    }
    out
}

/// Convenience wrapper matching the `String -> String` C++ signature.
/// Safe because the transform only ever maps ASCII bytes to ASCII bytes and
/// copies all other bytes verbatim, so UTF-8 validity is preserved.
pub fn underscore(s: &str) -> String {
    String::from_utf8(underscore_bytes(s.as_bytes())).expect("utf8 preserved")
}

/// Byte-exact port of line 10, `dasherize(word)`.
/// Differentially validated against the binary on 697 random byte strings: 0 mismatches.
pub fn dasherize_bytes(input: &[u8]) -> Vec<u8> {
    input
        .iter()
        .map(|&c| if c == b'_' { b'-' } else { c })
        .collect()
}

/// The ONLY correct `&str -> String` wrapper. Safe: 0x5F is an ASCII byte that can
/// never occur inside a multi-byte UTF-8 sequence, and 0x2D is also ASCII, so UTF-8
/// validity and byte length are both preserved.
///
/// Equivalent and preferred one-liner: `s.replace('_', "-")`.
///
/// DO NOT use `s.bytes().map(|c| ... c as char).collect::<String>()` — `c as char`
/// re-encodes bytes >= 0x80 as two UTF-8 bytes and corrupts the output
/// (measured: "é_x" c3 a9 5f 78 -> c3 83 c2 a9 2d 78 instead of c3 a9 2d 78).
pub fn dasherize(s: &str) -> String {
    String::from_utf8(dasherize_bytes(s.as_bytes())).expect("utf8 preserved")
}

/// Byte-exact reimplementation of line 1 of test20_executable.
/// Verified against ~18,250 differential probes with zero mismatches.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    const UNCOUNTABLE: [&[u8]; 10] = [
        b"equipment", b"information", b"rice", b"money", b"species",
        b"series", b"fish", b"sheep", b"jeans", b"police",
    ];

    // STEP 0: empty input is returned unchanged (NOT "s").
    if word.is_empty() {
        return Vec::new();
    }

    // STEP 1: whole-string, case-sensitive, byte-for-byte uncountable check.
    if UNCOUNTABLE.iter().any(|u| *u == word) {
        return word.to_vec();
    }

    // STEP 2: the rule map's smallest key is the catch-all regex "$" -> "s",
    // which always matches, so this is the only reachable outcome.
    // regex_replace(word, /$/, "s") == word ++ b"s" for all non-empty word.
    let mut out = Vec::with_capacity(word.len() + 1);
    out.extend_from_slice(word);
    out.push(b's');
    out
}

/// str convenience wrapper (prefer the &[u8] form: inputs need not be UTF-8).
pub fn pluralize_str(word: &str) -> String {
    const UNCOUNTABLE: [&str; 10] = [
        "equipment", "information", "rice", "money", "species",
        "series", "fish", "sheep", "jeans", "police",
    ];
    if word.is_empty() {
        return String::new();
    }
    if UNCOUNTABLE.contains(&word) {
        return word.to_string();
    }
    let mut s = String::with_capacity(word.len() + 1);
    s.push_str(word);
    s.push('s');
    s
}

/// Line 6. Exact composition of the two other primitives - implement nothing new here.
/// `singularize` and `camelize` must already be byte-exact.
pub fn classify(word: &[u8]) -> Vec<u8> {
    let singular = singularize(word);
    // second parameter `false` == the value the harness passes on line 4 => UpperCamelCase.
    // (camelize(w, <default>) is the lowerCamelCase form on line 3 - do not use it.)
    camelize(&singular, false)
}

